// Read-only phrase-wrapper, descriptor rate gate and attacked-group list.
import ghidra.app.emulator.EmulatorHelper;import java.io.*;import java.nio.file.*;
public class ZNativeFeedbackAuxOracle extends ZNativeWorldEffectOracle{
 static final long U=0x5e30c8,P=0x1900000,A=0x1920000,MIX=0x1930000;
 int sounds;long[] draw={0x4695e0,0x468fc0,0x469da0,0x469450,0x46a1a0,0x4688b0,0x46a3c0};
 void invoke(EmulatorHelper e,long entry,long ecx,long...args)throws Exception{e.writeRegister("ESP",S);put(e,S,4,RET);for(int i=0;i<args.length;i++)put(e,S+4+i*4,4,args[i]);e.writeRegister("ECX",ecx);if(!e.run(toAddr(entry),null,monitor))throw new Exception(e.getLastError());while(e.readRegister("EIP").longValue()!=RET){long pc=e.readRegister("EIP").longValue(),sp=e.readRegister("ESP").longValue();if(pc==MIX)sounds++;e.writeRegister("EAX",0);long ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){EmulatorHelper e=new EmulatorHelper(currentProgram);try{
  e.setBreakpoint(toAddr(RET));for(long a:draw)e.setBreakpoint(toAddr(a));e.writeMemory(toAddr(P),Files.readAllBytes(Path.of("C:/GOG Games/Z/PHRASES.BIN")));put(e,0x64c8a4,4,P);int s=0;for(int row:new int[]{22,24,25,27,26,30})for(int twice=0;twice<2;twice++){int length=(int)read(e,P+row*552+4,4);put(e,0x49c644,2,row);put(e,0x6809a4,2,length);put(e,0x6809a8,2,15);put(e,0x5849cb,1,4);put(e,0x64f7d4,2,0);put(e,0x66656c,2,0);put(e,0x4a69fc,4,twice);put(e,0x622da0,1,0);for(int tick=0;tick<32;tick++){invoke(e,0x46ade0,0);out.println("{\"kind\":0,\"scenario\":"+s+++",\"mode\":"+read(e,0x5849cb,1)+",\"phrase\":"+read(e,0x49c644,2)+",\"counter\":"+read(e,0x64f7d4,2)+",\"frame\":"+read(e,0x66656c,2)+",\"enabled\":"+read(e,0x47705e,1)+"}");}}
  e.setBreakpoint(toAddr(MIX));put(e,0x474214,4,MIX);put(e,0x6815a0,4,A);put(e,A,2,1);put(e,A+2,2,152);put(e,A+26,2,0);put(e,A+44+2,2,-1);for(s=0;s<512;s++){int now=(short)(s*997),last=s%7==0?now:s%11==0?(short)(now-32768):(short)(s*991);put(e,0x680d08,2,now);put(e,A+28,2,last);sounds=0;invoke(e,0x46e660,152);out.println("{\"kind\":1,\"scenario\":"+s+",\"result\":"+e.readRegister("EAX").longValue()+",\"last\":"+read(e,A+28,2)+",\"sounds\":"+sounds+"}");}
  for(s=0;s<512;s++){e.writeMemory(toAddr(U),new byte[240*192]);for(int i=0;i<240;i++){long u=U+i*192;put(e,u+49,1,4+i/3%4|(i%17==0?16:0));put(e,u+105,1,(i+s)%5<2?128:0);put(e,u+95,1,i%13==0?255:(i*19+s)%73);put(e,u+44,2,s*17-32000+i*101);put(e,u+46,2,s*23+30000-i*199);}put(e,0x622dc2,1,s%4);put(e,0x4d07e0,2,s*31);put(e,0x4d07a0,2,s*47);put(e,0x4a941a,1,1);invoke(e,0x432c30,0);int count=((int)read(e,0x4d07e4,4)-0x585930)/8,h=0x811c9dc5;for(int i=0;i<count;i++){int slot=((int)read(e,0x585930+i*8,4)-(int)U)/192;h=(h^slot)*16777619;h=(h^(int)read(e,0x585934+i*8,4))*16777619;}out.println("{\"kind\":2,\"scenario\":"+s+",\"count\":"+count+",\"listHash\":"+(h&0xffffffffL)+",\"membershipHash\":"+hash(e.readMemory(toAddr(0x4d0688),240))+",\"dirty\":"+read(e,0x4a941a,1)+"}");}
 }finally{e.dispose();}}}
}
